import { useState, useMemo, useCallback, memo, Profiler } from 'react';

// Performance profiler wrapper
function onRenderCallback(id, phase, actualDuration) {
  if (actualDuration > 16) {
    console.warn(`Slow render [${id}]: ${actualDuration.toFixed(1)}ms (${phase})`);
  }
}

// Heavy child — should only re-render when quests or filters change
const QuestList = memo(function QuestList({ quests, filters, onAccept }) {
  return (
    <ul data-testid="quest-list">
      {quests
        .filter(q => q.status === filters.status)
        .map(q => (
          <li key={q.id}>
            {q.title}
            <button onClick={() => onAccept(q.id)}>Accept</button>
          </li>
        ))}
    </ul>
  );
});

export default function App() {
  const [search, setSearch] = useState('');
  const [accepted, setAccepted] = useState([]);

  const allQuests = [
    { id: 1, title: 'Slay Dragon', status: 'OPEN' },
    { id: 2, title: 'Find Tome', status: 'OPEN' },
    { id: 3, title: 'Brew Potion', status: 'CLOSED' },
  ];

  // TODO: Fix 1 — inline object causes QuestList to re-render on every search keystroke
  const filters = { status: 'OPEN' };

  // TODO: Fix 2 — inline function creates new reference every render
  const handleAccept = (id) => setAccepted(prev => [...prev, id]);

  // TODO: Fix 3 — filtered quests recomputed on every render even when allQuests/search unchanged
  const filteredQuests = allQuests.filter(q =>
    q.title.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <Profiler id="App" onRender={onRenderCallback}>
      <div data-testid="app">
        <input
          data-testid="search"
          value={search}
          onChange={e => setSearch(e.target.value)}
          placeholder="Search quests"
        />
        <QuestList
          quests={filteredQuests}
          filters={filters}
          onAccept={handleAccept}
        />
        <p data-testid="accepted">Accepted: {accepted.length}</p>
      </div>
    </Profiler>
  );
}
